package io.github.describeadmin.codegen.parser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.describeadmin.codegen.model.ModuleSpec;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class SpecLoaderMutaGate1Test {

    private static Map<String, Object> baseRoot() {
        Map<String, Object> field = new LinkedHashMap<>();
        field.put("name", "orderNo");
        field.put("type", "string");
        field.put("length", 32);

        Map<String, Object> root = new LinkedHashMap<>();
        root.put("basePackage", "com.example.demo");
        root.put("module", "work_order");
        root.put("entity", "WorkOrder");
        root.put("table", "biz_work_order");
        root.put("fields", List.of(field));
        return root;
    }

    @Test
    void defaultsExplicitValuesAndErrorPrefixing() {
        // Defaults: comment falls back to entity, apiPrefix derives from module with '_' -> '-'
        ModuleSpec defaults = SpecLoader.parse(baseRoot(), "a.yaml", "nested");
        assertEquals("WorkOrder", defaults.comment());
        assertEquals("/api/work-order", defaults.apiPrefix());
        assertEquals("orderNo", defaults.fields().get(0).comment());
        assertEquals("order_no", defaults.fields().get(0).column());
        assertEquals("--layout 参数", defaults.layoutOrigin());

        // Explicit values are kept (and trimmed)
        Map<String, Object> explicit = baseRoot();
        explicit.put("comment", "  工单  ");
        explicit.put("apiPrefix", "/custom/orders");
        ModuleSpec given = SpecLoader.parse(explicit, "a.yaml", "nested");
        assertEquals("工单", given.comment());
        assertEquals("/custom/orders", given.apiPrefix());

        // Non-map root: single error with source prefix
        SpecException notMap = assertThrows(SpecException.class,
                () -> SpecLoader.parse("just a string", "root.yaml", "nested"));
        assertEquals(List.of("root.yaml: 根节点必须是对象（key: value 形式）"), notMap.errors());

        // Empty map: all required keys missing plus missing fields, each prefixed with source
        SpecException empty = assertThrows(SpecException.class,
                () -> SpecLoader.parse(new HashMap<String, Object>(), "my.yaml", "nested"));
        assertEquals(5, empty.errors().size());
        for (String e : empty.errors()) {
            assertTrue(e.startsWith("my.yaml: "), e);
        }
        assertTrue(empty.errors().contains("my.yaml: 缺少 fields"));
        assertTrue(empty.errors().stream().anyMatch(e -> e.contains("缺少必填项 basePackage")));
        assertTrue(empty.errors().stream().anyMatch(e -> e.contains("缺少必填项 table")));
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.Layout;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate2Test {

    @Test
    void invalidValuesAreReportedWithOriginAndDoNotFallThrough() {
        // 1) 非法的命令行取值：只记一条错误，来源为 --layout 参数，
        //    不会因为 spec / 环境变量合法而继续往下取值；错误信息里的取值已 trim
        List<String> errors = new ArrayList<>();
        SpecLoader.LayoutChoice cli = SpecLoader.resolveLayout("  bogus  ", "flat", "flat", errors);
        assertEquals("--layout 参数", cli.origin());
        assertEquals(Layout.NESTED, cli.layout());
        assertEquals(1, errors.size());
        assertTrue(errors.get(0).contains("\"bogus\""), errors.get(0));
        assertTrue(errors.get(0).contains("来自 --layout 参数"), errors.get(0));
        assertTrue(errors.get(0).contains("只能是 nested 或 flat"), errors.get(0));

        // 2) 非法的 spec 取值（非字符串类型，经 String.valueOf 转换）：
        //    只记一条错误，来源为 spec 的 layout 键，不会改用合法的环境变量
        errors = new ArrayList<>();
        SpecLoader.LayoutChoice spec = SpecLoader.resolveLayout(null, 123, "flat", errors);
        assertEquals("spec 的 layout 键", spec.origin());
        assertEquals(Layout.NESTED, spec.layout());
        assertEquals(1, errors.size());
        assertTrue(errors.get(0).contains("\"123\""), errors.get(0));
        assertTrue(errors.get(0).contains("来自 spec 的 layout 键"), errors.get(0));

        // 3) 合法的命令行取值不会被后面非法的 spec / 环境变量影响，也不产生错误
        errors = new ArrayList<>();
        SpecLoader.LayoutChoice ok = SpecLoader.resolveLayout("flat", "sideways", "bogus", errors);
        assertEquals(Layout.FLAT, ok.layout());
        assertEquals("--layout 参数", ok.origin());
        assertTrue(errors.isEmpty(), errors.toString());

        // 4) 环境变量非法时，错误信息中的取值同样 trim
        errors = new ArrayList<>();
        SpecLoader.LayoutChoice env = SpecLoader.resolveLayout(null, null, " weird ", errors);
        assertEquals("CODEGEN_LAYOUT 环境变量", env.origin());
        assertEquals(1, errors.size());
        assertTrue(errors.get(0).contains("\"weird\""), errors.get(0));
    }
}

package io.github.describeadmin.codegen.parser;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class SpecLoaderMutaGate3Test {

    @Test
    void toSnakeEdgeCases() {
        // empty string
        assertEquals("", SpecLoader.toSnake(""));
        // already snake / lower: unchanged
        assertEquals("abc", SpecLoader.toSnake("abc"));
        assertEquals("a_b", SpecLoader.toSnake("a_b"));
        // each uppercase letter gets its own underscore (no acronym merging)
        assertEquals("a_b_c", SpecLoader.toSnake("aBC"));
        assertEquals("owner_dept_id", SpecLoader.toSnake("ownerDeptId"));
        // leading uppercase produces a leading underscore
        assertEquals("_abc", SpecLoader.toSnake("Abc"));
        // digits are kept in place and do not trigger underscores
        assertEquals("field1_name2", SpecLoader.toSnake("field1Name2"));
        // trailing uppercase
        assertEquals("item_x", SpecLoader.toSnake("itemX"));
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.Layout;
import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate4Test {

    @TempDir
    Path tmp;

    @Test
    void loadReadsUtf8FileAndReportsErrorsWithFileNameOnly() throws Exception {
        String yaml = """
                basePackage: com.example.demo
                module: work_order
                entity: WorkOrder
                table: biz_work_order
                comment: 工单管理
                fields:
                  - name: title
                    type: string
                    length: 64
                    comment: 工单标题
                """;
        Path good = tmp.resolve("good.yaml");
        Files.writeString(good, yaml, StandardCharsets.UTF_8);

        ModuleSpec spec = SpecLoader.load(good, "flat");
        assertEquals("工单管理", spec.comment());
        assertEquals("工单标题", spec.fields().get(0).comment());
        assertEquals(Layout.FLAT, spec.layout());
        assertEquals("--layout 参数", spec.layoutOrigin());
        assertEquals("/api/work-order", spec.apiPrefix());
        assertEquals("com.example.demo.controller", spec.packageOf("controller"));

        // 单参数重载等价于 layoutOverride = null：回落到默认（或环境变量）
        ModuleSpec viaSingleArg = SpecLoader.load(good);
        assertEquals("工单管理", viaSingleArg.comment());

        // 错误信息里的来源只用文件名，不带目录
        Path dir = Files.createDirectory(tmp.resolve("some-nested-dir"));
        Path bad = dir.resolve("bad.yaml");
        Files.writeString(bad, "just a string", StandardCharsets.UTF_8);

        SpecException ex = assertThrows(SpecException.class, () -> SpecLoader.load(bad, null));
        List<String> errors = ex.errors();
        assertEquals(1, errors.size());
        assertTrue(errors.get(0).startsWith("bad.yaml: "), errors.get(0));
        assertFalse(errors.get(0).contains("some-nested-dir"), errors.get(0));
    }
}

