package io.github.describeadmin.codegen.parser;

import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate6Test {

    @Test
    void parseRejectsNonObjectRootAndPrefixesErrorsWithSource() {
        String expectedRootError = "my.yaml: 根节点必须是对象（key: value 形式）";

        for (Object badRoot : new Object[] {null, "just a string", List.of("a", "b"), 42}) {
            SpecException ex = assertThrows(SpecException.class,
                    () -> SpecLoader.parse(badRoot, "my.yaml"));
            assertEquals(List.of(expectedRootError), ex.errors());
        }

        SpecException ex = assertThrows(SpecException.class,
                () -> SpecLoader.parse(Map.of(), "other.yaml"));
        List<String> errors = ex.errors();
        assertTrue(errors.size() >= 5, "应一次报出所有缺失项: " + errors);
        for (String e : errors) {
            assertTrue(e.startsWith("other.yaml: "), "错误应带来源前缀: " + e);
        }
        assertTrue(errors.contains(
                "other.yaml: 缺少必填项 basePackage（业务方基础包名，如 com.example.demo）"));
        assertTrue(errors.contains("other.yaml: 缺少 fields"));
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;
import org.yaml.snakeyaml.Yaml;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate7Test {

    @Test
    void parseDefaultsOverridesAndErrorPrefixes() {
        // 1. 缺省值：comment 取 entity，apiPrefix 把下划线换成连字符，字段缺省属性
        String defaults = """
                basePackage: com.example.demo
                module: work_order
                entity: WorkOrder
                table: biz_work_order
                fields:
                  - name: workNo
                    type: int
                """;
        ModuleSpec s = SpecLoader.parse(new Yaml().load(defaults), "a.yaml", "nested");
        assertEquals("WorkOrder", s.comment());
        assertEquals("/api/work-order", s.apiPrefix());
        assertEquals("work_order", s.module());
        FieldSpec f = s.fields().get(0);
        assertEquals("work_no", f.column());
        assertEquals("workNo", f.comment());
        assertTrue(f.nullable());
        assertFalse(f.indexed());
        assertEquals(FieldSpec.QueryMode.NONE, f.query());
        assertNull(f.length());

        // 2. 显式 comment / apiPrefix 优先
        String explicit = defaults + "comment: 工单\napiPrefix: /custom/wo\n";
        ModuleSpec e = SpecLoader.parse(new Yaml().load(explicit), "a.yaml", "nested");
        assertEquals("工单", e.comment());
        assertEquals("/custom/wo", e.apiPrefix());

        // 3. 根节点不是对象：单条错误，带 source 前缀
        SpecException notMap = assertThrows(SpecException.class,
                () -> SpecLoader.parse(List.of("x"), "root.yaml", "nested"));
        assertEquals(List.of("root.yaml: 根节点必须是对象（key: value 形式）"), notMap.errors());

        // 4. 全部缺失：每条错误都带 source 前缀，并包含必填项与 fields 提示
        SpecException missing = assertThrows(SpecException.class,
                () -> SpecLoader.parse(new Yaml().load("comment: x\n"), "src.yaml", "nested"));
        assertTrue(missing.errors().size() >= 5);
        for (String err : missing.errors()) {
            assertTrue(err.startsWith("src.yaml: "), err);
        }
        String joined = String.join("\n", missing.errors());
        assertTrue(joined.contains("缺少必填项 basePackage"));
        assertTrue(joined.contains("缺少必填项 module"));
        assertTrue(joined.contains("缺少必填项 entity"));
        assertTrue(joined.contains("缺少必填项 table"));
        assertTrue(joined.contains("缺少 fields"));

        // 5. fields 为空数组且其余合法：给出专门提示
        String emptyFields = """
                basePackage: com.example.demo
                module: project
                entity: Project
                table: biz_project
                fields: []
                """;
        SpecException empty = assertThrows(SpecException.class,
                () -> SpecLoader.parse(new Yaml().load(emptyFields), "e.yaml", "nested"));
        assertEquals(1, empty.errors().size());
        assertTrue(empty.errors().get(0).startsWith("e.yaml: fields 为空"));

        // 6. entity 带 Entity 后缀被拦下
        String suffix = defaults.replace("entity: WorkOrder", "entity: WorkOrderEntity");
        SpecException se = assertThrows(SpecException.class,
                () -> SpecLoader.parse(new Yaml().load(suffix), "s.yaml", "nested"));
        assertTrue(String.join("\n", se.errors()).contains("不要带 Entity 后缀"));

        // 7. 非法包名被拦下
        String badPkg = defaults.replace("com.example.demo", "Com.Example");
        SpecException pe = assertThrows(SpecException.class,
                () -> SpecLoader.parse(new Yaml().load(badPkg), "p.yaml", "nested"));
        assertTrue(String.join("\n", pe.errors()).contains("不是合法包名"));
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.Layout;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

class SpecLoaderMutaGate8Test {

    @Test
    void invalidValuesAreReportedWithOriginAndShortCircuit() {
        // illegal CLI value wins over valid lower-priority sources; only one error, naming the CLI origin
        List<String> errors = new ArrayList<>();
        SpecLoader.LayoutChoice cli = SpecLoader.resolveLayout("bogus", "flat", "flat", errors);
        assertThat(cli.origin()).isEqualTo("--layout 参数");
        assertThat(cli.layout()).isEqualTo(Layout.NESTED);
        assertThat(errors).hasSize(1);
        assertThat(errors.get(0))
                .contains("\"bogus\"")
                .contains("来自 --layout 参数")
                .contains("只能是 nested 或 flat")
                .doesNotContain("spec 的 layout 键")
                .doesNotContain("CODEGEN_LAYOUT");

        // non-string spec value is stringified and reported
        List<String> specErrors = new ArrayList<>();
        SpecLoader.LayoutChoice spec = SpecLoader.resolveLayout(null, 123, "flat", specErrors);
        assertThat(spec.origin()).isEqualTo("spec 的 layout 键");
        assertThat(specErrors).hasSize(1);
        assertThat(specErrors.get(0))
                .contains("\"123\"")
                .contains("来自 spec 的 layout 键");

        // env value is trimmed in the message
        List<String> envErrors = new ArrayList<>();
        SpecLoader.LayoutChoice env = SpecLoader.resolveLayout(null, null, "  bogus ", envErrors);
        assertThat(env.origin()).isEqualTo("CODEGEN_LAYOUT 环境变量");
        assertThat(envErrors).hasSize(1);
        assertThat(envErrors.get(0)).contains("\"bogus\"").contains("来自 CODEGEN_LAYOUT 环境变量");

        // errors accumulate in the caller's list rather than being replaced
        List<String> shared = new ArrayList<>();
        shared.add("existing");
        SpecLoader.resolveLayout("bad1", null, null, shared);
        SpecLoader.resolveLayout(null, "bad2", null, shared);
        assertThat(shared).hasSize(3);
        assertThat(shared.get(0)).isEqualTo("existing");
        assertThat(shared.get(1)).contains("bad1");
        assertThat(shared.get(2)).contains("bad2");

        // valid input leaves the list untouched
        List<String> clean = new ArrayList<>();
        assertThat(SpecLoader.resolveLayout(null, null, null, clean).origin()).isEqualTo("默认");
        assertThat(clean).isEmpty();
    }
}

package io.github.describeadmin.codegen.parser;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class SpecLoaderMutaGate9Test {

    @Test
    void toSnakeBehavior() {
        // empty string stays empty
        assertEquals("", SpecLoader.toSnake(""));
        // already lowercase is unchanged
        assertEquals("name", SpecLoader.toSnake("name"));
        // each uppercase letter gets an underscore before it
        assertEquals("a_b_c", SpecLoader.toSnake("aBC"));
        // leading uppercase yields leading underscore
        assertEquals("_name", SpecLoader.toSnake("Name"));
        // digits are preserved and do not trigger underscores
        assertEquals("field2_name", SpecLoader.toSnake("field2Name"));
        // existing underscores are kept as-is
        assertEquals("a__b", SpecLoader.toSnake("a_B"));
        // consecutive capitals each get an underscore
        assertEquals("parse_x_m_l", SpecLoader.toSnake("parseXML"));
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.Layout;
import io.github.describeadmin.codegen.model.ModuleSpec;
